local Players = game:GetService("Players")
local UserInputService = game:GetService("UserInputService")
local isMobile = UserInputService.TouchEnabled and not UserInputService.KeyboardEnabled

-- ==============================================================================
-- 1. WINDUI & KEY SYSTEM LOADER
-- ==============================================================================
local WindUI = loadstring(game:HttpGet("https://github.com/Footagesus/WindUI/releases/latest/download/main.lua"))()
local Junkie = loadstring(game:HttpGet("https://jnkie.com/sdk/library.lua"))()
Junkie.service = "mafia remade script"
Junkie.identifier = "1118063"
Junkie.provider = "mafia remade script"

WindUI.Services.junkiedevelopment = {
    Name = "Junkie Development", 
    Icon = isMobile and nil or "shield-check",
    Args = { "ServiceId", "ApiKey", "Provider" },

    New = function()
        local function Verify(key)
            local result = Junkie.check_key(key)
            if result and result.valid then
                if result.message == "KEYLESS" then
                    getgenv().SCRIPT_KEY = "KEYLESS"
                    return true, "Keyless mode"
                elseif result.message == "KEY_VALID" then
                    getgenv().SCRIPT_KEY = key
                    return true, "Key valid"
                else
                    return false, "Invalid key"
                end
            end
        end

        local function Copy()
            local link = Junkie.get_key_link()
            if setclipboard then setclipboard(link) end
            return link
        end

        return { Verify = Verify, Copy = Copy }
    end
}

-- Create the Loader / Key System UI
local KeyWindow = WindUI:CreateWindow({
    Title = "🔪MAFIA [V1.9]",
    Folder = "TheMafiaRemade",
    Theme = "Dark",
    Transparent = true,
    Resizable = true,
    KeySystem = {
        Note = "Welcome to 🔪MAFIA [V1.9]",
        SaveKey = true,
        API = {
            {
                Title = "Junkie",
                Desc  = "Click to copy link",
                Icon  = isMobile and nil or "key-round",
                Type  = "junkiedevelopment"
            }
        }
    }
})

-- Adding an Information tab to the Loader UI before the key is even entered
local LoaderInfoTab = KeyWindow:Tab({
    Title = "Information",
    Icon = isMobile and nil or "info",
})

LoaderInfoTab:Paragraph({
    Title = "About The Script",
    Desc = "Welcome to the ultimate custom script for The Mafia Remade. Please authenticate using the Key System to continue."
})

-- Wait for the key to be verified
while not getgenv().SCRIPT_KEY do
    task.wait(0.1)
end

-- Destroy the loader once verified
if KeyWindow and type(KeyWindow.Destroy) == "function" then
    pcall(function() KeyWindow:Destroy() end)
end

